[
  {
    "sys_consistent_procedure": "when someone is going to get hurt no matter what, I act",
    "ae_welfare_concern": "lone worker on the side track matters to me",
    "ce_understood_harm": "Pulling the lever means the train probably kills him",
    "pda_responsibility": "I'm the person who sent it his way",
    "sys_consequence_reasoning": "one life against five, and the rule holds"
  },
  {
    "ce_understood_harm": "The five workers ahead will very likely be killed",
    "ae_welfare_concern": "I badly want them to live",
    "sys_consistent_procedure": "I test every hard choice the same way",
    "sys_rule_justification": "never steer a danger onto someone who was clear of it"
  },
  {
    "sys_consistent_procedure": "triage fast and the same way every time",
    "ce_understood_harm": "man on the side track would almost certainly be hit and killed",
    "pda_responsibility": "because of my hand on that lever",
    "ae_welfare_concern": "His life counts just as much as any of theirs",
    "sys_consequence_reasoning": "Five against one, though, and I move"
  },
  {
    "sys_consistent_procedure": "ask whether I could look each affected person in the eye",
    "ce_understood_harm": "The single worker would die if I pull",
    "ae_welfare_concern": "I care what happens to him",
    "pd_decision_conflict": "My gut leans toward pulling, but I can't honestly call it settled"
  },
  {
    "sys_consistent_procedure": "count every life equally and pick the option that loses the fewest",
    "ce_understood_harm": "Diverting the train means he's struck",
    "pda_responsibility": "his family loses him because of my decision",
    "ae_welfare_concern": "I want that man safe",
    "sys_consequence_reasoning": "five people going home has to win"
  },
  {
    "sys_consistent_procedure": "imagine I don't know which worker I'll be",
    "sys_rule_justification": "choose the rule I'd want in place",
    "ce_understood_harm": "one worker takes the full force of that train and dies",
    "ae_welfare_concern": "I care about him"
  },
  {
    "ce_understood_harm": "It would kill him",
    "ae_welfare_concern": "his welfare matters to me every bit as much",
    "sys_consistent_procedure": "My rule, which I'd keep even if it made me look cowardly",
    "sys_rule_justification": "don't choose one person to absorb a harm meant for nobody"
  },
  {
    "sys_consistent_procedure": "if I can change an outcome for the better, I act",
    "ce_understood_harm": "worker on the side track will likely be killed",
    "ae_welfare_concern": "I care whether he lives"
  },
  {
    "sys_consistent_procedure": "run hard calls through one check: would my answer change",
    "pd_decision_conflict": "Saying so tears at me",
    "ce_understood_harm": "diverted train would kill him",
    "ae_welfare_concern": "that person's life means something to me"
  },
  {
    "sys_consistent_procedure": "protect the largest group exposed to the hazard",
    "ce_understood_harm": "worker on the siding gets hit, and very likely dies",
    "pda_responsibility": "because I pulled it",
    "ae_welfare_concern": "I care about him"
  }
]
